"""Mutation fuzzer for the wire validation (development tool)."""
import copy, json, os, random, subprocess, sys

BASE = {
    "version": 3,
    "cases": [{
        "model": "cnn",
        "class_values": [1, 2, 3, 4, 5, 6, 7],
        "stats": [1, 1, 75],
        "bucket": [1, 1],
        "slots": [[0, 1, 0], [2, 1, 1]],
        "flows": [[1, 1, -1, 2], [2, 3, 0, 4]],
        "groups": [[-1, 5]],
        "windows": [[0, 0, 2, 1, 1, 0, 1, [[0, 0]] * 9],
                    [1, 0, 2, 1, 1, 0, 1, [[5, 5]] * 9]],
    }],
}

WEIRD = [None, True, False, 0, -1, 1.5, 1e0, "x", [], {}, [1, 2], {"a": 1},
         10 ** 20, -10 ** 20, 65536, 513, 1e400]


def paths(obj, prefix=()):
    out = [prefix]
    if isinstance(obj, dict):
        for k, v in obj.items():
            out.extend(paths(v, prefix + (k,)))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            out.extend(paths(v, prefix + (i,)))
    return out


def get(obj, path):
    for step in path:
        obj = obj[step]
    return obj


def set_path(obj, path, value):
    for step in path[:-1]:
        obj = obj[step]
    obj[path[-1]] = value


def run(raw):
    env = dict(os.environ)
    env['LD_LIBRARY_PATH'] = '/workspace/native'
    p = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'],
                       input=raw, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                       env=env, timeout=60)
    return p.returncode, p.stdout.decode(), p.stderr.decode()


def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    bad = 0
    for _ in range(rounds):
        case = copy.deepcopy(BASE)
        all_paths = paths(case)
        for _ in range(rng.randint(1, 3)):
            path = rng.choice(all_paths)
            if not path:
                continue
            action = rng.random()
            if action < 0.5:
                set_path(case, path, rng.choice(WEIRD))
            elif action < 0.75:
                # drop a key from a dict
                parent = get(case, path[:-1]) if len(path) > 1 else case
                if isinstance(parent, dict) and parent:
                    key = rng.choice(list(parent))
                    del parent[key]
            else:
                # truncate a list
                parent = get(case, path[:-1]) if len(path) > 1 else case
                if isinstance(parent, list) and len(parent) > 1:
                    del parent[rng.randrange(len(parent))]
        raw = json.dumps(case).encode()
        code, out, err = run(raw)
        if code != 0:
            print('EXIT %d: %s' % (code, err[:300])); bad += 1; continue
        try:
            response = json.loads(out)
        except ValueError:
            print('BAD JSON: %r' % out[:200]); bad += 1; continue
        if 'error' in response:
            if response != {'error': 'invalid'}:
                print('BAD ERROR PAYLOAD: %r' % response); bad += 1
        else:
            # a mutated request may still be valid; make sure it looks sane
            if response.get('version') != 3 or 'results' not in response:
                print('BAD RESPONSE SHAPE: %r' % response); bad += 1
    print('fuzz done, %d problems' % bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
PYEOF
